SELECT s.id AS special_id, s.store_scope, s.member_only, i.material_id, i.special_price, i.discount_rate, i.limit_qty
FROM pos_special_item i
JOIN pos_special s ON s.id = i.special_id
WHERE s.status = 'ACTIVE' AND s.channel IN ('POS', 'ALL') AND s.begin_time <= #{now} AND s.end_time >= #{now}
  AND i.material_id IN
  #{id}
